import{_ as a,o as i,c as o,a2 as t}from"./chunks/framework.Buc7gXeZ.js";const m=JSON.parse('{"title":"Dynamic Record View Engine","description":"","frontmatter":{},"headers":[],"relativePath":"dynamic-record-view/README.md","filePath":"dynamic-record-view/README.md"}'),r={name:"dynamic-record-view/README.md"};function n(d,e,l,c,s,h){return i(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="dynamic-record-view-engine" tabindex="-1">Dynamic Record View Engine <a class="header-anchor" href="#dynamic-record-view-engine" aria-label="Permalink to &quot;Dynamic Record View Engine&quot;">​</a></h1><p>A framework for building record detail (&quot;show&quot;) pages declaratively, the same way <code>App\\Support\\DynamicTable</code> builds list pages. This is the final, closed-out state of the engine: core definitions, authorized record resolution, the Primary section (fields/tabs), an independent Other Data section, read-only embedding of existing Dynamic Tables, Link/Unlink relationship mutation, the searchable Relation Picker, and security/eager-loading hardening are all implemented and tested.</p><p>The only genuinely unfinished pieces are: a multi-select Relation Picker, a real <code>reassignPolicy()</code> hook (currently a throwing stub), and a <code>BelongsToMany</code> Link/Unlink path exercised against a real <code>BelongsToMany</code> relation (the code path is written but nothing in this codebase uses <code>BelongsToMany</code> to test it against). See <a href="./relationship-actions">relationship-actions.md</a> and <a href="./relation-picker">relation-picker.md</a> for exact status.</p><h2 id="layers" tabindex="-1">Layers <a class="header-anchor" href="#layers" aria-label="Permalink to &quot;Layers&quot;">​</a></h2><ul><li><strong>Core</strong> (<code>app/Support/DynamicRecordView/Core/</code>) — framework-agnostic. No Livewire, no Blade, no <code>Modules\\*</code>, no application Eloquent models. Architecture-tested in <code>tests/Feature/DynamicRecordView/ArchitectureTest.php</code>.</li><li><strong>Resolution</strong> (<code>app/Support/DynamicRecordView/Resolution/</code>) — <code>RecordResolver</code> resolves a record only through its view&#39;s authorized <code>query()</code>, with required relations eager-loaded; <code>RelationshipMutator</code> performs Link/Unlink transactionally; <code>EmbeddedTableContext</code> resolves an embedded table&#39;s parent/content.</li><li><strong>Livewire</strong> (<code>app/Livewire/DynamicRecordView/</code>) — <code>RecordView</code> (Primary section), <code>OtherData</code> (independent Other Data section), <code>RelationPickerModal</code> (Link candidate search + confirm).</li><li><strong>Blade</strong> (<code>resources/views/components/dynamic-record-view/</code>, <code>resources/views/livewire/dynamic-record-view/</code>) — rendering, Flux Free only.</li></ul><h2 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h2><ul><li><a href="./quick-start">quick-start.md</a> — build a record view in a few minutes.</li><li><a href="./architecture">architecture.md</a> — how the layers fit together and why.</li><li><a href="./defining-record-views">defining-record-views.md</a>, <a href="./sections-tabs">sections-tabs.md</a>, <a href="./content-blocks">content-blocks.md</a>, <a href="./fields">fields.md</a> — the Core API.</li><li><a href="./record-resolution">record-resolution.md</a> — authorization and 404 behavior.</li><li><a href="./embedded-tables">embedded-tables.md</a>, <a href="./relations">relations.md</a>, <a href="./sub-applications">sub-applications.md</a> — embedding existing Dynamic Tables and declaring Sub Applications.</li><li><a href="./relationship-actions">relationship-actions.md</a>, <a href="./relation-picker">relation-picker.md</a> — Link/Unlink and the candidate picker.</li><li><a href="./state-isolation">state-isolation.md</a> — stable vs. instance keys for embedded/tab state.</li><li><a href="./security">security.md</a> — URL allowlisting, fail-closed registry, transactional mutation, state normalization.</li><li><a href="./performance">performance.md</a> — eager-loading and query-count guarantees.</li><li><a href="./authorization">authorization.md</a> — every authorization hook in the engine.</li><li><a href="./request-lifecycle">request-lifecycle.md</a> — a request traced end to end.</li><li><a href="./accessibility">accessibility.md</a> — current a11y state, honestly.</li><li><a href="./extending">extending.md</a> — adding a new field type, content block, or record view.</li><li><a href="./troubleshooting">troubleshooting.md</a> — common errors and fixes.</li><li><a href="./package-extraction">package-extraction.md</a> — what it would take to extract this into a standalone package.</li><li><a href="./testing">testing.md</a> — how the existing test suite is organized.</li></ul><h2 id="canonical-examples" tabindex="-1">Canonical examples <a class="header-anchor" href="#canonical-examples" aria-label="Permalink to &quot;Canonical examples&quot;">​</a></h2><ul><li><strong>SubModule -&gt; Applications</strong> (<code>hasMany</code>, non-nullable FK): <code>Modules\\General\\System\\SubModuleRecordView</code> (Core definition) + <code>Modules\\General\\Livewire\\SubModuleRecordView</code> (Livewire page), reachable at <code>route(&#39;general.sub-modules.view&#39;, [&#39;recordId&#39; =&gt; $subModule-&gt;id])</code>. Its Other Data section embeds the real <code>SubModule::applications()</code> relation via <code>Modules\\General\\Livewire\\ApplicationsTable</code>, with Link-only relationship actions (see <a href="./relationship-actions">relationship-actions.md</a>).</li><li><strong>Country -&gt; Cities</strong> (<code>hasMany</code>, non-nullable FK, geographic/<code>nnjeim/world</code> data): <code>Modules\\General\\System\\World\\CountryRecordView</code>, reachable at <code>route(&#39;general.world.countries.show&#39;, [&#39;recordId&#39; =&gt; $country-&gt;id])</code>. Its Other Data section embeds <code>Modules\\General\\Livewire\\World\\Countries\\CitiesTable</code>, also Link-only for the same non-nullable-FK reason.</li></ul>',9)])])}const p=a(r,[["render",n]]);export{m as __pageData,p as default};
